# Test hatalı tutar fonksiyonu
def tutar_hatali(metin):
    metin = metin.strip()
    if "," in metin:
        tam, kurus = metin.split(",")
        return float(tam.replace(".", "")) + float(kurus) / 100
    return float(metin)

print("89,90 ->", tutar_hatali("89,90"))  # 8990.90 (YANLIŞ!)
print("7.250,50 ->", tutar_hatali("7.250,50"))  # 725050.50 (ÇOK YANLIŞ!)
print("32.500 ->", tutar_hatali("32.500"))  # float("32.500") -> 32.5 (Doğru ama noktalar silinmeli)

